"""Page traces of real algorithms, generated by simulating their memory addresses.

Each generator lays its arrays out one after another (page aligned), runs
the algorithm, records the address of every array element it reads or
writes, and turns addresses into page numbers. Consecutive references to the
same page are collapsed, as in a classic reference string.

The page size is scaled down (64 bytes by default) so that inputs small
enough to simulate quickly in Python still touch hundreds to thousands of
pages. Only the shape of the access pattern matters to replacement policies.
"""

from __future__ import annotations

import numpy as np


def _layout(sizes: list[int], page_bytes: int) -> list[int]:
    """Base address of each array when placed back to back on page boundaries."""
    bases, addr = [], 0
    for size in sizes:
        bases.append(addr)
        addr += -(-size // page_bytes) * page_bytes
    return bases


def _to_pages(addresses, page_bytes: int) -> list[int]:
    pages = np.asarray(addresses, dtype=np.int64) // page_bytes
    keep = np.ones(len(pages), dtype=bool)
    keep[1:] = pages[1:] != pages[:-1]
    return pages[keep].tolist()


def matmul_trace(n: int = 40, page_bytes: int = 64) -> list[int]:
    """Naive i-j-k multiplication of two n x n row-major double matrices, C = A x B.

    A is read along rows (good locality), B down columns (a new page almost
    every step) and C written once per element.
    """
    elem = 8
    a_base, b_base, c_base = _layout([n * n * elem] * 3, page_bytes)
    i, j, k = np.indices((n, n, n)).reshape(3, -1)  # k varies fastest
    refs = np.empty((n * n, 2 * n + 1), dtype=np.int64)
    refs[:, 0 : 2 * n : 2] = (a_base + (i * n + k) * elem).reshape(n * n, n)
    refs[:, 1 : 2 * n : 2] = (b_base + (k * n + j) * elem).reshape(n * n, n)
    ii, jj = np.indices((n, n)).reshape(2, -1)
    refs[:, 2 * n] = c_base + (ii * n + jj) * elem
    return _to_pages(refs.ravel(), page_bytes)


def mergesort_trace(n: int = 8192, page_bytes: int = 64, seed: int = 0) -> list[int]:
    """Bottom-up merge sort of n random 4-byte integers, ping-ponging between two buffers."""
    rng = np.random.default_rng(seed)
    elem = 4
    src_base, dst_base = _layout([n * elem] * 2, page_bytes)
    src, dst = rng.permutation(n).tolist(), [0] * n
    refs: list[int] = []
    width = 1
    while width < n:
        for lo in range(0, n, 2 * width):
            mid, hi = min(lo + width, n), min(lo + 2 * width, n)
            i, j = lo, mid
            for k in range(lo, hi):
                if i < mid and (j >= hi or src[i] <= src[j]):
                    refs.append(src_base + i * elem)
                    dst[k] = src[i]
                    i += 1
                else:
                    refs.append(src_base + j * elem)
                    dst[k] = src[j]
                    j += 1
                refs.append(dst_base + k * elem)
        src, dst = dst, src
        src_base, dst_base = dst_base, src_base
        width *= 2
    return _to_pages(refs, page_bytes)


def bfs_trace(
    n_nodes: int = 6000,
    degree: int = 5,
    runs: int = 2,
    local_share: float = 0.5,
    page_bytes: int = 64,
    seed: int = 0,
) -> list[int]:
    """Breadth-first search over a random graph in CSR form, repeated from several sources.

    Half of each node's edges go to nearby node ids (some locality), the rest
    to random nodes. The visited array is cleared before every run.
    """
    rng = np.random.default_rng(seed)
    n = n_nodes
    local = rng.random((n, degree)) < local_share
    near = (np.arange(n)[:, None] + rng.integers(-20, 21, (n, degree))) % n
    far = rng.integers(0, n, (n, degree))
    adj = np.where(local, near, far).ravel().tolist()
    offsets = list(range(0, n * degree + 1, degree))

    off_base, adj_base, vis_base, queue_base = _layout([(n + 1) * 4, len(adj) * 4, n, n * 4], page_bytes)
    refs: list[int] = []
    for _ in range(runs):
        refs.extend(range(vis_base, vis_base + n, page_bytes))  # clear the visited array
        visited = bytearray(n)
        source = int(rng.integers(0, n))
        visited[source] = 1
        queue = [source]
        refs += [vis_base + source, queue_base]
        head = 0
        while head < len(queue):
            u = queue[head]
            refs += [queue_base + 4 * head, off_base + 4 * u, off_base + 4 * (u + 1)]
            head += 1
            for e in range(offsets[u], offsets[u + 1]):
                v = adj[e]
                refs += [adj_base + 4 * e, vis_base + v]
                if not visited[v]:
                    visited[v] = 1
                    refs.append(queue_base + 4 * len(queue))
                    queue.append(v)
    return _to_pages(refs, page_bytes)
